#include "inference.h"
#include <stdint.h>
#include <math.h>    // expf — links via libm (included by default in Vitis Cortex-A9 BSP)
#include <stdio.h>   // printf — supports %f on bare-metal Vitis, unlike xil_printf

// ================================================================
//  STATIC BUFFERS
//  Total: ~60 KB in BSS (zero-initialized, no stack cost).
//
//  fc_weights[1352][10] = 54080 bytes — by far the largest.
//  This MUST be static/global. Putting it on stack will corrupt
//  the Zynq bare-metal stack silently (no MMU, no guard page).
//
//  pool_output_f: 1352 floats = 5408 bytes.
//  fc_out, softmax_out: 10 floats each = trivial.
// ================================================================
static float pool_output_f[8 * 13 * 13];  // 1352 elements, 5408 bytes
static float fc_weights[1352][10];         // 54080 bytes
static float fc_bias[10];
static float fc_out[10];
static float softmax_out[10];

// ================================================================
//  LCG WEIGHT INIT
//  Simple linear congruential generator — reproducible across runs,
//  no stdlib rand() dependency. Scale ±0.05 ≈ Xavier init for
//  fan_in=1352: sqrt(1/1352) ≈ 0.027. ±0.05 is close enough that
//  softmax won't saturate and top-3 scores will be distinguishable.
// ================================================================
static uint32_t lcg_state = 0xDEADBEEF;

static float lcg_randf(void) {
    lcg_state = lcg_state * 1664525u + 1013904223u;
    // High 16 bits have better statistical quality in LCGs
    return ((float)(lcg_state >> 16) / 65535.0f) * 0.1f - 0.05f;
}

